import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"ADR 0001 — Capacitor as the shell technology","description":"","frontmatter":{"status":"Accepted","date":"2026-07-31T00:00:00.000Z","deciders":"kasunben","sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/adrs/0001-capacitor-as-shell-technology.md"},"headers":[],"relativePath":"apps/mobile/adrs/0001-capacitor-as-shell-technology.md","filePath":"apps/mobile/adrs/0001-capacitor-as-shell-technology.md"}'),i={name:"apps/mobile/adrs/0001-capacitor-as-shell-technology.md"};function r(n,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0001-—-capacitor-as-the-shell-technology" tabindex="-1">ADR 0001 — Capacitor as the shell technology <a class="header-anchor" href="#adr-0001-—-capacitor-as-the-shell-technology" aria-label="Permalink to &quot;ADR 0001 — Capacitor as the shell technology&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted. Locked by sovereign RFC 0058 and reaffirmed in sovereign workstream 0002&#39;s &quot;Decisions locked&quot; table before this repository was created; recorded here as this repo&#39;s own decision of record.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Sovereign needs one native mobile client that loads a user&#39;s self-hosted instance without duplicating the platform&#39;s auth, plugin, or shell logic. It must ship a single binary that works against any instance URL, share as much logic and mental model as possible with the already-shipped <code>sovereign-desktop</code> (Tauri) shell, and expose native device capabilities to plugin authors through a portable SDK surface.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Build the shell with <strong>Capacitor</strong> (TypeScript-first, WKWebView on iOS, Android System WebView on Android).</p><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Hotwire Native.</strong> Requires separate native bridge code per platform, working against the &quot;one TypeScript-first shell logic&quot; goal this repo shares with <code>sovereign-desktop</code>.</li><li><strong>React Native.</strong> Rebuilds the platform UI as a second client rendered natively — the opposite of the &quot;thin WebView wrapper, source of truth stays the instance&quot; model this repo exists to implement. (Note: <code>sovereign-edge</code>, a separate and unrelated repository, does use React Native — but it is building a real native app with its own UI by design, not a WebView shell. Its rationale does not transfer here.)</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Shell logic stays TypeScript, matching <code>sovereign-desktop</code> and the rest of the Sovereign codebase; native Swift/Kotlin is used only where a Capacitor plugin genuinely requires it.</li><li>Device capability access goes through Capacitor plugins, fronted by the shared <code>sdk.device.*</code> contract (see <a href="./0004-shared-device-bridge-contract-with-desktop.html">ADR 0004</a>).</li><li>iOS and Android project files are committed to this repo (see <a href="./../epics/shell.html">epics/shell.md</a>, task 20.1).</li></ul>',11)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
